/* ---------- Шапка внутренних страниц, крошки, 404 ---------- */
.svr-page-hero{padding-block:var(--wp--preset--spacing--60) var(--wp--preset--spacing--50);border-bottom:1px solid var(--svr-line)}
.svr-crumbs{gap:6px 10px;font-size:.9375rem;line-height:1.4}
.svr-crumbs a{display:inline-block;padding-block:13px;margin-block:-13px;color:var(--svr-ink-2);text-decoration:none}
.svr-crumbs a:hover{color:var(--svr-ink);text-decoration:underline}
.svr-crumbs__sep{color:var(--svr-muted)}
.svr-crumbs .svr-crumbs__current{margin:0;font-size:.9375rem;font-weight:400;line-height:1.4;letter-spacing:0;color:var(--svr-muted)}
.svr-page-hero .svr-page-title{max-width:18em;margin-top:32px}
.svr-404 .wp-block-columns{gap:clamp(32px,5vw,88px);align-items:center!important}
.svr-404 .wp-block-column.is-layout-flow>*+*{margin-block-start:28px}
.svr-404 .svr-404__dwg{max-width:340px;margin-left:auto;opacity:.5}
.svr-404 .svr-footer__links{columns:2;column-gap:32px;max-width:28rem}
@media (max-width:1023px){.svr-404 .svr-404__dwg{display:none}.svr-404 .wp-block-column{flex-basis:100%!important}}

/* ---------- Галерея объекта, lightbox ---------- */
.wp-block-gallery.has-nested-images.svr-gallery{--wp--style--unstable-gallery-gap:32px;gap:32px}
.wp-block-gallery.has-nested-images.svr-gallery figure.wp-block-image{aspect-ratio:740/354;align-items:center;justify-content:center;margin:0;background:var(--svr-surface);border:1px solid var(--svr-line);border-radius:var(--svr-r-card);overflow:hidden}
.wp-block-gallery.has-nested-images.svr-gallery figure.wp-block-image img{width:auto;height:auto;max-height:100%;object-fit:contain}
.wp-block-gallery.has-nested-images.svr-gallery figure.wp-block-image.svr-on-paper{padding:16px;background:var(--svr-paper)}
.wp-block-gallery.has-nested-images.svr-gallery figure.wp-block-image.svr-native img{max-width:477px!important;margin-inline:auto}
.svr-gallery figure.wp-block-image:hover{border-color:var(--svr-cyan)}
@media (min-width:782px){.wp-block-gallery.has-nested-images.svr-gallery figure.wp-block-image:last-child:nth-child(odd){flex-grow:0}}
@media (max-width:781px){.wp-block-gallery.has-nested-images.svr-gallery{--wp--style--unstable-gallery-gap:24px;gap:24px}.wp-block-gallery.has-nested-images.svr-gallery figure.wp-block-image:not(#individual-image){width:100%}}
.wp-lightbox-overlay .scrim{background-color:rgba(4,17,31,.94)!important}
.wp-lightbox-overlay .close-button{color:var(--svr-ink)}
.wp-lightbox-overlay img{border-radius:var(--svr-r-sm);background-color:var(--svr-paper)}
.svr-sheet__img button:focus-visible,.svr-on-paper button:focus-visible{outline-color:var(--svr-paper-accent)}

/* ---------- Подвал ---------- */
.svr-footer{padding-block:var(--wp--preset--spacing--70) var(--wp--preset--spacing--50);background-color:var(--svr-deep);border-top:1px solid var(--svr-line);color:var(--svr-ink-2)}
.svr-footer__grid.is-layout-grid{gap:48px 72px}
.svr-footer__grid>*{margin:0}
.svr-footer .is-layout-flow>*+*{margin-block-start:16px}
.svr-footer .svr-footer__h{font-size:.8125rem;font-weight:700;line-height:1.4;letter-spacing:.12em;text-transform:uppercase;color:var(--svr-muted)}
.svr-footer__logo img{display:block;height:44px;width:auto}
.wp-block-image.svr-footer__logo{margin:0}
.svr-footer__contacts a{color:var(--svr-ink);text-decoration:none}
.svr-footer__contacts a:hover{color:var(--svr-cyan);text-decoration:underline}
.svr-footer__contacts .svr-footer__phone{font-size:var(--wp--preset--font-size--large);font-weight:600;white-space:nowrap}
.svr-footer__links{margin:0;padding:0;list-style:none}
.svr-footer__links>li{margin:0}
.svr-footer__links>li+li{margin-top:8px}
.svr-footer__links a{display:inline-flex;align-items:center;min-height:32px;color:var(--svr-ink);text-decoration:none}
.svr-footer__links a:hover{color:var(--svr-cyan);text-decoration:underline}
.svr-footer .svr-footer__req{align-items:flex-start;gap:16px 64px;margin-top:var(--wp--preset--spacing--60);padding-top:var(--wp--preset--spacing--50);border-top:1px solid var(--svr-line)}
.svr-footer__req>*{flex:1 1 260px;margin:0;font-size:var(--wp--preset--font-size--small);line-height:1.7;color:var(--svr-muted)}
.svr-footer__req code{font-size:.875rem;color:var(--svr-ink-2)}
.svr-footer .svr-footer__bar{gap:8px 24px;margin-top:var(--wp--preset--spacing--40);font-size:.9375rem;color:var(--svr-muted)}
.svr-footer__bar>*{margin:0}
@media (min-width:1024px){.svr-footer__grid.is-layout-grid{grid-template-columns:1.5fr 1fr 1.3fr}}
@media (max-width:1023px){.svr-footer__grid.is-layout-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.svr-footer__grid>:first-child{grid-column:1/-1}}
@media (max-width:781px){.svr-footer__links a,.svr-footer__contacts a{min-height:44px}.svr-footer__contacts a{display:inline-flex;align-items:center}}
@media (max-width:599px){.svr-footer__grid.is-layout-grid{grid-template-columns:minmax(0,1fr)}}
@media (pointer:coarse){.svr-footer__links a,.svr-footer__contacts a{display:inline-flex;align-items:center;min-height:44px}.svr-topbar a{display:inline-block;padding-block:12px;margin-block:-12px}}

/* ---------- Движение (только no-preference) ---------- */
@media (prefers-reduced-motion:no-preference){
html{scroll-behavior:smooth}
.svr-nav .wp-block-navigation-item__content::after,.svr-btn--ghost>.wp-block-button__link::before{transition:transform .35s var(--svr-ease)}
.svr-btn--ghost>.wp-block-button__link::after,.svr-sheet__tb::after,.svr-obj__body::after,.svr-mini-obj::after,.svr-phone a::after{transition:transform .3s var(--svr-ease)}
.svr-sheet,.svr-obj,.svr-doc-sheet img{transition:transform .5s var(--svr-ease),box-shadow .5s var(--svr-ease)}
.svr-obj::after{transition:opacity .4s var(--svr-ease)}
.wp-block-image.svr-obj__img::before{transition:opacity .8s var(--svr-ease)}
.wp-block-image.svr-obj__img img{transition:transform .8s var(--svr-ease)}
.svr-hero__text>*{animation:svr-rise .9s var(--svr-ease) both}
.svr-hero__text>:nth-child(2){animation-delay:.1s}.svr-hero__text>:nth-child(3){animation-delay:.2s}.svr-hero__text>:nth-child(4){animation-delay:.3s}.svr-hero__text>:nth-child(5){animation-delay:.4s}
.svr-hero .svr-dwg{animation:svr-fade 1.2s ease .2s both}
.svr-dwg-wave{animation:svr-wave 10s linear infinite}
.svr-dwg-wave.svr-dwg-wave--back{animation-duration:16s;animation-direction:reverse}
.svr-dwg-bubble{animation:svr-bubble 8s ease-in infinite}
@supports (animation-timeline:view()){
@media (min-width:782px){.svr-sheet,.svr-obj,.svr-stage,.svr-card{animation:svr-reveal linear both;animation-timeline:view();animation-range:entry 0% entry 30%}}}
@keyframes svr-rise{from{opacity:.01;translate:0 16px}to{opacity:1;translate:0 0}}
@keyframes svr-fade{from{opacity:0}to{opacity:1}}
@keyframes svr-reveal{from{opacity:.001;translate:0 24px}to{opacity:1;translate:0 0}}
@keyframes svr-wave{from{transform:translateX(0)}to{transform:translateX(-120px)}}
@keyframes svr-bubble{0%{transform:translateY(0);opacity:0}15%{opacity:1}80%{opacity:.8}100%{transform:translateY(-150px);opacity:0}}}
@media (prefers-reduced-motion:reduce){.svr-dwg-bubble{display:none}}

/* ---------- Редактор: растянутые ссылки не перекрывают блоки (селектор с .editor-styles-wrapper редактор не префиксует, на сайте его нет) ---------- */
.editor-styles-wrapper .svr-sheet__name a::after,.editor-styles-wrapper .svr-obj .wp-block-heading a::after,.editor-styles-wrapper .svr-mini-obj .wp-block-heading a::after{display:none}
.editor-styles-wrapper :is(.svr-sheet,.svr-obj,.svr-stage,.svr-card){animation:none;opacity:1;translate:none}

/* ---------- Печать, принудительные цвета ---------- */
@media print{
*,*::before,*::after{animation:none!important;transition:none!important}
.svr-sheet,.svr-obj,.svr-stage,.svr-card{opacity:1!important;transform:none!important;translate:none!important}
.wp-site-blocks>header.wp-block-template-part{position:static}
.svr-header::before,.svr-mm::before{display:none}}
@media (forced-colors:active){
mark.has-inline-color{color:CanvasText!important;background:none!important;-webkit-text-fill-color:CanvasText}
.svr-matrix td :is(strong,em){forced-color-adjust:none}
.svr-matrix td strong{background:CanvasText}
.svr-matrix td em{background:linear-gradient(CanvasText,CanvasText) center/12px 1px no-repeat}
.wp-element-button,.wp-block-button__link{border-color:ButtonText}
.svr-btn--ghost>.wp-block-button__link::after{forced-color-adjust:none;background:LinkText}
.wp-block-button:not(.svr-btn--ghost):is(.svr-ic-tel,.svr-ic-mail,.svr-ic-doc,.svr-ic-arrow,.svr-ic-ext)>.wp-block-button__link::before{forced-color-adjust:none;background:ButtonText}
.svr-obj__body::after,.svr-mini-obj::after,.svr-sheet__tb::after{forced-color-adjust:none;background:CanvasText}
.svr-stage__ico{forced-color-adjust:none;color:CanvasText;background:Canvas;box-shadow:inset 0 0 0 1px CanvasText}
.svr-header::before{background:Canvas;-webkit-backdrop-filter:none;backdrop-filter:none}}
